  // Theme toggle
  const toggle = document.getElementById('themeToggle');
  const body = document.body;
  const stored = localStorage.getItem('theme') || 'dark';
  body.setAttribute('data-theme', stored);
  toggle.addEventListener('click', () => {
    const next = body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    body.setAttribute('data-theme', next);
    localStorage.setItem('theme', next);
  });

  // Scroll progress
  window.addEventListener('scroll', () => {
    const scrolled = window.scrollY;
    const total = document.documentElement.scrollHeight - window.innerHeight;
    document.getElementById('progress-bar').style.width = (scrolled / total * 100) + '%';
  });

  // SPA Navigation - active nav handled by showPage()

  // Scroll reveal
  const revealObs = new IntersectionObserver((entries) => {
    entries.forEach(el => {
      if (el.isIntersecting) { el.target.classList.add('revealed'); el.target.classList.add('visible'); }
    });
  }, { threshold: 0.1 });
  document.querySelectorAll('.reveal').forEach(el => revealObs.observe(el));

  // SPA Navigation
  function showPage(pageId) {
    document.querySelectorAll('.page-section').forEach(s => s.classList.remove('active-page'));
    const target = document.getElementById(pageId);
    if (target) {
      target.classList.add('active-page');
      // Trigger reveal for all elements in this section
      target.querySelectorAll('.reveal').forEach(el => {
        el.classList.add('visible');
        el.classList.add('revealed');
      });
    }
    document.querySelectorAll('.nav-links a').forEach(a => {
      a.classList.toggle('active', a.dataset.page === pageId);
    });
    window.scrollTo(0, 0);
  }

  document.querySelectorAll('[data-page]').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      showPage(a.dataset.page);
    });
  });

  // Floating contact toggle
  const floatToggle = document.getElementById('float-toggle');
  const floatMenu = document.getElementById('float-menu');
  floatToggle.addEventListener('click', () => {
    floatToggle.classList.toggle('open');
    floatMenu.classList.toggle('open');
  });
  document.addEventListener('click', (e) => {
    if (!e.target.closest('#float-contact')) {
      floatToggle.classList.remove('open');
      floatMenu.classList.remove('open');
    }
  });

  // Certificate PDF openers
  const certData = {
    compiler: '',
    google: '',
    flipkart: '',
    internship: ''
  };
  function openCert(key) {
    const b64 = certData[key];
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const blob = new Blob([bytes], {type: 'application/pdf'});
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  }

